CREATE TABLE IF NOT EXISTS instruments (instrument_key VARCHAR(100) PRIMARY KEY, symbol VARCHAR(40) NOT NULL, name VARCHAR(160) NOT NULL, segment VARCHAR(30) NOT NULL, lot_size INTEGER, exchange_token VARCHAR(40), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE INDEX IF NOT EXISTS ix_instruments_symbol ON instruments(symbol);
CREATE TABLE IF NOT EXISTS universe_versions (version VARCHAR(32) PRIMARY KEY, refreshed_at TIMESTAMPTZ NOT NULL, count INTEGER NOT NULL, snapshot_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS market_sessions (session_date TIMESTAMPTZ PRIMARY KEY, status VARCHAR(24) NOT NULL, open_at TIMESTAMPTZ, close_at TIMESTAMPTZ, source VARCHAR(40) NOT NULL DEFAULT 'calendar');
CREATE TABLE IF NOT EXISTS signals (signal_id VARCHAR(32) PRIMARY KEY, symbol VARCHAR(40) NOT NULL, module VARCHAR(40) NOT NULL, direction VARCHAR(8) NOT NULL, setup VARCHAR(40) NOT NULL, timestamp TIMESTAMPTZ NOT NULL, entry DOUBLE PRECISION NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', relation VARCHAR(20) NOT NULL DEFAULT 'INDEPENDENT');
CREATE INDEX IF NOT EXISTS ix_signals_symbol ON signals(symbol);
CREATE INDEX IF NOT EXISTS ix_signals_module ON signals(module);
CREATE INDEX IF NOT EXISTS ix_signals_timestamp ON signals(timestamp);
CREATE INDEX IF NOT EXISTS ix_signals_symbol_module_time ON signals(symbol,module,timestamp);
CREATE TABLE IF NOT EXISTS signal_events (id BIGSERIAL PRIMARY KEY, signal_id VARCHAR(32) NOT NULL REFERENCES signals(signal_id) ON DELETE CASCADE, event VARCHAR(40) NOT NULL, timestamp TIMESTAMPTZ NOT NULL DEFAULT now(), payload_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS ix_signal_events_signal_id ON signal_events(signal_id);
CREATE TABLE IF NOT EXISTS risk_levels (signal_id VARCHAR(32) PRIMARY KEY REFERENCES signals(signal_id) ON DELETE CASCADE, entry DOUBLE PRECISION NOT NULL, stop_loss DOUBLE PRECISION NOT NULL, target_1 DOUBLE PRECISION NOT NULL, target_2 DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS active_trades (signal_id VARCHAR(32) PRIMARY KEY REFERENCES signals(signal_id) ON DELETE CASCADE, state_json TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS alert_outbox (id BIGSERIAL PRIMARY KEY, alert_id VARCHAR(32) UNIQUE NOT NULL REFERENCES signals(signal_id) ON DELETE CASCADE, body TEXT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'PENDING', attempts INTEGER NOT NULL DEFAULT 0, lease_owner VARCHAR(120), lease_until TIMESTAMPTZ, last_error TEXT);
CREATE INDEX IF NOT EXISTS ix_alert_outbox_status ON alert_outbox(status);
CREATE INDEX IF NOT EXISTS ix_outbox_status_lease ON alert_outbox(status,lease_until);
CREATE TABLE IF NOT EXISTS alert_deliveries (id BIGSERIAL PRIMARY KEY, alert_id VARCHAR(32) NOT NULL REFERENCES alert_outbox(alert_id) ON DELETE CASCADE, attempt INTEGER NOT NULL, attempted_at TIMESTAMPTZ NOT NULL DEFAULT now(), status VARCHAR(16) NOT NULL, response_json TEXT, error TEXT, CONSTRAINT uq_delivery_attempt UNIQUE(alert_id,attempt));
CREATE INDEX IF NOT EXISTS ix_alert_deliveries_alert_id ON alert_deliveries(alert_id);
CREATE TABLE IF NOT EXISTS module_state (key VARCHAR(160) PRIMARY KEY, value_json TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS system_health (id BIGSERIAL PRIMARY KEY, component VARCHAR(80) NOT NULL, status VARCHAR(24) NOT NULL, checked_at TIMESTAMPTZ NOT NULL DEFAULT now(), details_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS ix_system_health_component ON system_health(component);
CREATE TABLE IF NOT EXISTS backtest_runs (run_id VARCHAR(40) PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), module VARCHAR(40) NOT NULL, symbol VARCHAR(40) NOT NULL, params_json TEXT NOT NULL, metrics_json TEXT NOT NULL, report_path VARCHAR(255));
